SELECT code as codecd, code as code, cdnm as codenm, cdnm as cdnm, remark as etcval, remark as remark
FROM hsba900t_tbl
WHERE useyn = 'Y'

    AND cmpycd = #{cmpycd}


    AND cdgbn = #{gbncd}


    AND code = #{code}

ORDER BY dspord

SELECT custcd, custnm, ceo, telno, address FROM haba020t_tbl WHERE cmpycd = #{cmpycd}
AND custnm LIKE CONCAT('%', #{custnm}, '%')
ORDER BY custnm
